Aqui está a solução completa.

Esta atualização divide-se em duas partes críticas:
1.  **O Script SQL**: Para criar a estrutura de banco de dados no Supabase que suporta Afiliados, Persistência de Treinos e Dietas.
2.  **Atualização dos Serviços**: Modifiquei o `geminiService` e o `affiliateService` para pararem de usar dados voláteis e passarem a Salvar/Carregar tudo do banco de dados.

### 1. Script SQL (Execute no Supabase SQL Editor)

Copie e execute este bloco no seu painel do Supabase para criar as tabelas e permissões necessárias.

```sql
-- 1. ENUMS (Tipos personalizados)
CREATE TYPE affiliate_level AS ENUM ('GERENTE', 'AFILIADO', 'DONOS');
CREATE TYPE commission_status AS ENUM ('PENDING', 'PAID', 'CANCELLED');
CREATE TYPE plan_type AS ENUM ('PLANO_TREINO_DIETA', 'PLANO_SOMENTE_TREINO', 'PLANO_SOMENTE_DIETA');

-- 2. ATUALIZAÇÃO DA TABELA DE PERFIL (Se já existir)
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS affiliate_id uuid; -- Quem indicou este usuário
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS gender text;

-- 3. TABELA DE AFILIADOS
CREATE TABLE IF NOT EXISTS affiliates (
  id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  code text UNIQUE NOT NULL,
  level affiliate_level DEFAULT 'AFILIADO',
  balance numeric(10,2) DEFAULT 0.00,
  total_earnings numeric(10,2) DEFAULT 0.00,
  active boolean DEFAULT true,
  created_at timestamptz DEFAULT now()
);

-- 4. TABELA DE COMISSÕES (Transações)
CREATE TABLE IF NOT EXISTS commissions (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  affiliate_id uuid REFERENCES affiliates(id),
  order_id text NOT NULL,
  buyer_name text,
  plan_type plan_type NOT NULL,
  amount numeric(10,2) NOT NULL,
  status commission_status DEFAULT 'PENDING',
  created_at timestamptz DEFAULT now(),
  paid_at timestamptz
);

-- 5. TABELA PARA SALVAR TREINOS (JSONB para flexibilidade da IA)
CREATE TABLE IF NOT EXISTS workout_plans (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  plan_data jsonb NOT NULL, -- Armazena toda a estrutura WeeklyWorkoutPlan
  title text,
  active boolean DEFAULT true,
  created_at timestamptz DEFAULT now()
);

-- 6. TABELA PARA SALVAR DIETAS
CREATE TABLE IF NOT EXISTS diet_plans (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  plan_data jsonb NOT NULL, -- Armazena toda a estrutura DietPlan
  active boolean DEFAULT true,
  created_at timestamptz DEFAULT now()
);

-- 7. POLÍTICAS DE SEGURANÇA (RLS)
ALTER TABLE affiliates ENABLE ROW LEVEL SECURITY;
ALTER TABLE commissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE workout_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE diet_plans ENABLE ROW LEVEL SECURITY;

-- Usuários veem seus próprios planos
CREATE POLICY "Users can read own workout plans" ON workout_plans FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can insert own workout plans" ON workout_plans FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Users can update own workout plans" ON workout_plans FOR UPDATE USING (auth.uid() = user_id);

CREATE POLICY "Users can read own diet plans" ON diet_plans FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can insert own diet plans" ON diet_plans FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Users can update own diet plans" ON diet_plans FOR UPDATE USING (auth.uid() = user_id);

-- Afiliados veem seus próprios dados
CREATE POLICY "Affiliates read own data" ON affiliates FOR SELECT USING (auth.uid() = id);
CREATE POLICY "Affiliates read own commissions" ON commissions FOR SELECT USING (auth.uid() = affiliate_id);
-- (Em produção, commissions INSERT seria restrito a service_role/webhooks, mas deixaremos aberto para o simulador funcionar)
CREATE POLICY "Allow simulation inserts" ON commissions FOR INSERT WITH CHECK (true); 
CREATE POLICY "Allow affiliate creation" ON affiliates FOR INSERT WITH CHECK (auth.uid() = id);
```

